    diagonal_right &lt;- list(c(input4_matrix[i + 2, j], input4_matrix[i + 1, j + 1], input4_matrix[i, j + 2]))
    if (count_pattern(diagonal_left, &#039;MAS&#039;) + count_pattern(diagonal_right, &#039;MAS&#039;) == 2) x_mas_count &lt;- x_mas_count + 1
  }
